// Lab check for the managed-settings drop-ins: merge them in name order, then test the rules we rely on.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const dir = process.argv[2] ?? "settings/managed-settings.d";
const merged: Record<string, unknown> = {};
for (const name of readdirSync(dir).filter((f) => f.endsWith(".json")).sort()) {
  Object.assign(merged, JSON.parse(readFileSync(join(dir, name), "utf8"))); // lab merge: a later file wins per key
}
const problems: string[] = [];
const markets = (merged.strictKnownMarketplaces ?? []) as Array<{ repo?: string }>;
if (!markets.some((m) => m.repo === "RhinoHealth/*")) problems.push("strictKnownMarketplaces must allow RhinoHealth/*");
if (merged.allowManagedMcpServersOnly !== true) problems.push("allowManagedMcpServersOnly must be true");
for (const server of (merged.allowedMcpServers ?? []) as Array<{ serverUrl?: string }>) {
  if (!server.serverUrl?.startsWith("https://")) problems.push(`MCP server is not an https URL: ${JSON.stringify(server)}`);
}
if (!((merged.deniedModels ?? []) as string[]).includes("fable")) problems.push("deniedModels must keep fable (G0-12)");
for (const key of ["model", "availableModels", "effortLevel"]) {
  if (key in merged) problems.push(`${key} must not be set: people keep Anthropic's defaults (G0-12)`);
}
console.log(problems.length === 0 ? "policy ok" : problems.join("\n"));
process.exitCode = problems.length === 0 ? 0 : 1;

